import org.junit.jupiter.api.BeforeEach;
import static org.junit.jupiter.api.Assertions.*;

class Add_escapesTests {

    private ParseException parseException;

    @BeforeEach
    void setUp() {
        parseException = new ParseException();
    }

    @Test
    void testAddEscapes_NullInput() {
        assertThrows(NullPointerException.class, () -> {
            parseException.add_escapes(null);
        });
    }

    @Test
    void testAddEscapes_EmptyString() {
        String result = parseException.add_escapes("");
        assertEquals("", result);
    }

    @Test
    void testAddEscapes_NoSpecialCharacters() {
        String input = "Hello World 123";
        String result = parseException.add_escapes(input);
        assertEquals(input, result);
    }

    @Test
    void testAddEscapes_Backspace() {
        String input = "Hello\bWorld";
        String result = parseException.add_escapes(input);
        assertEquals("Hello\\bWorld", result);
    }

    @Test
    void testAddEscapes_Tab() {
        String input = "Hello\tWorld";
        String result = parseException.add_escapes(input);
        assertEquals("Hello\\tWorld", result);
    }

    @Test
    void testAddEscapes_Newline() {
        String input = "Hello\nWorld";
        String result = parseException.add_escapes(input);
        assertEquals("Hello\\nWorld", result);
    }

    @Test
    void testAddEscapes_FormFeed() {
        String input = "Hello\fWorld";
        String result = parseException.add_escapes(input);
        assertEquals("Hello\\fWorld", result);
    }

    @Test
    void testAddEscapes_CarriageReturn() {
        String input = "Hello\rWorld";
        String result = parseException.add_escapes(input);
        assertEquals("Hello\\rWorld", result);
    }

    @Test
    void testAddEscapes_DoubleQuote() {
        String input = "Hello\"World";
        String result = parseException.add_escapes(input);
        assertEquals("Hello\\\"World", result);
    }

    @Test
    void testAddEscapes_SingleQuote() {
        String input = "Hello\'World";
        String result = parseException.add_escapes(input);
        assertEquals("Hello\\\'World", result);
    }

    @Test
    void testAddEscapes_Backslash() {
        String input = "Hello\\World";
        String result = parseException.add_escapes(input);
        assertEquals("Hello\\\\World", result);
    }

    @Test
    void testAddEscapes_MultipleSpecialCharacters() {
        String input = "\b\t\n\f\r\"\'\\";
        String result = parseException.add_escapes(input);
        assertEquals("\\b\\t\\n\\f\\r\\\"\\\'\\\\", result);
    }

    @Test
    void testAddEscapes_NonPrintableASCII() {
        String input = String.valueOf((char) 1) + "Test" + (char) 31;
        String result = parseException.add_escapes(input);
        assertEquals("\\u0001Test\\u001f", result);
    }

    @Test
    void testAddEscapes_PrintableASCII() {
        StringBuilder input = new StringBuilder();
        for (int i = 32; i <= 126; i++) {
            input.append((char) i);
        }
        String result = parseException.add_escapes(input.toString());
        assertEquals(input.toString(), result);
    }

    @Test
    void testAddEscapes_UnicodeCharacters() {
        String input = "Hello\u00A9World";
        String result = parseException.add_escapes(input);
        assertEquals("Hello\\u00a9World", result);
    }

    @Test
    void testAddEscapes_MixedContent() {
        String input = "Line1\nLine2\tTab\"Quote\'Single\\Backslash\bBackspace";
        String result = parseException.add_escapes(input);
        assertEquals("Line1\\nLine2\\tTab\\\"Quote\\\'Single\\\\Backslash\\bBackspace", result);
    }

    @Test
    void testAddEscapes_AllControlCharacters() {
        StringBuilder input = new StringBuilder();
        StringBuilder expected = new StringBuilder();

        for (int i = 0; i < 32; i++) {
            input.append((char) i);
            if (i == '\b') {
                expected.append("\\b");
            } else if (i == '\t') {
                expected.append("\\t");
            } else if (i == '\n') {
                expected.append("\\n");
            } else if (i == '\f') {
                expected.append("\\f");
            } else if (i == '\r') {
                expected.append("\\r");
            } else if (i == '\"') {
                expected.append("\\\"");
            } else if (i == '\'') {
                expected.append("\\\'");
            } else if (i == '\\') {
                expected.append("\\\\");
            } else {
                expected.append(String.format("\\u%04x", i));
            }
        }

        String result = parseException.add_escapes(input.toString());
        assertEquals(expected.toString(), result);
    }

    @Test
    void testAddEscapes_StringWithSpaces() {
        String input = "  Hello  World  ";
        String result = parseException.add_escapes(input);
        assertEquals(input, result);
    }
}

